// Migration v3 to v4: the world becomes 3D (owner A, reviewed by B and E; EMBERCROWN-FORTRESS.md 5.4, Stage Z1 E9).
//
// A Stage 2 colony is one plane, W x H x 1. This turns it into a W x H x 20 fortress with the old plane as the
// surface level zS = 14, its mountain made real rock above it and the levels below generated by mapgen3 from the
// seed and a base mask computed once from the save. It is a pure function of the save and the seed: no live
// random stream is read or advanced (veins draw from `mig4:veins`, the levels below from mapgen3's `gen3:*`).
//
//   migrateWorld(s)       a live D = 1 state (stateVersion 3, s.rt built) -> the same object as a D = 20 state with
//                         its pristine world (worldKind 2) attached and s.rt rebuilt. Returns { s, pristine, info }.
//   migrateBlob(bytes)    an EC2 blob -> loadBlob (state migrations to v3) -> migrateWorld (tests, the loader at E13)
//   v3to4(ent)            (state.js; re-exported) the ENTITIES part, `migrations[2]` once STATE_VERSION is 4 (E13): it only marks
//                         ent.meta.world4 = true; the loader then calls migrateWorld on the built state, because the
//                         world step needs the layers, which an ENTITIES migration never sees (state.js 11.5).
//   checkMigrated(s, info) the 5.4 checks that need no old build (cover over old tunnels, nobody on AIR or in rock,
//                         every saved voxel index inside the map at z = zS, the pristine CRCs): [] when all hold.
//
// Steps (5.4): 1 world shape; 2 baseMask; 3 plane zS = the save's 12 layers (roof 2 and 3 cleared, fluid 0);
// 4 levels zS+1..zS+h rock of the column's stone, with ore veins by massif depth; 5 levels 0..zS-1 from
// mapgen3.generateBelow (belowOnly); 6 the pristine world (the dug plane as saved, steps 4 and 5, baseMask in the
// meta); 7 every entity z = zS; 8 every saved voxel index + zS * PLANE; 9 saved flow fields dropped, a live raid's
// morale = 100 - 3 x losses; 10 initRuntime and the Chronicle line.

import {
  W, H, PLANE, N, TER, ROOF, TER_FLOOR, TER_PASSABLE, setMapSize, allocLayers, LAYERS, idx, getBit, setBit,
} from './grid.js';
import { hashString, rint, rnd } from './rand.js';
import { mapVoxelRefs, newBuilding } from './schema.js';
import { initRuntime, v3to4 } from './state.js';
import { GEN3, DATA as GEN_DATA } from '../../data/worldgen.js';
import { baseMaskOf, generateBelow } from '../world/mapgen3.js';
import { depositId } from '../world/defs.js';
import { spawn as spawnItem } from '../work/items.js';
import { makePristine, attachPristine, layerCrcs } from '../save/pristine.js';
import { WORLD_KIND, PRISTINE_LAYERS, toBase64 } from '../save/codec.js';
import { loadBlob } from '../save/colonysave.js';

/** The shape of a migrated world (5.4 step 1). */
export const MIG4 = Object.freeze({ d: 20, zS: 14 });
export const CHRON_DEPTH = 'chron_depth';   // "the hold learned the depth of the world" (text: G, js/data/text/chronicle.js)

/** 5.4 ENTITIES step (state.js migrations[2] from E13): marks the save so the loader runs migrateWorld. */
export { v3to4 };

/** An EC2 blob (any state version) -> a migrated D = 20 state. */
export async function migrateBlob(bytes, opts = {}) {
  const s = await loadBlob(bytes);
  return migrateWorld(s, opts);
}

// ---- helpers ------------------------------------------------------------------------------------------
const gen = (seed) => ({ rng: { g: seed >>> 0 || 0x9e3779b9 } });
const ri = (R, a, b) => rint(R, 'g', a, b);
const rf = (R) => rnd(R, 'g');
const offTile = (v, off) => (Number.isInteger(v) && v >= 0 ? v + off : v);

/** Step 4: ore veins in the risen massif (zS+1..zS+h), by planar massif depth (the R2 3.2 table). */
function massifVeins(L, mask, depth2, zs, seed) {
  const R = gen(hashString(`mig4:veins:${seed >>> 0}`)), V = GEN3.vein, area = (W * H) / (128 * 128);
  const rules = [];
  for (const d of GEN_DATA.deposit) rules.push({ id: d.id, ore: depositId(d.id), veins: d.veins, lo: d.depth[0], hi: Math.min(d.depth[1], 12), gem: false });
  for (const v of GEN3.veins) if (v.massif) rules.push({ id: v.id, ore: depositId(v.id), veins: v.veins, lo: 1, hi: 12, gem: !!v.gem });
  const cols = [];
  for (let c = 0; c < PLANE; c++) if ((mask[c] & 16) && (mask[c] & 7)) cols.push(c);
  const stats = {};
  if (!cols.length) return stats;
  const ok = (i, rule) => {
    const z = (i / PLANE) | 0, c = i % PLANE;
    return z > zs && z <= zs + (mask[c] & 7) && L.terrain[i] === TER.ROCK && !L.ore[i] && depth2[c] >= rule.lo && depth2[c] <= rule.hi;
  };
  for (const rule of rules) {
    if (!(rule.ore > 0)) continue;
    const want = Math.max(1, Math.round(ri(R, rule.veins[0], rule.veins[1]) * area * cols.length / PLANE));
    let placed = 0, cells = 0;
    for (let v = 0; v < want; v++) {
      let cur = -1;
      for (let k = 0; k < V.tries; k++) {
        const c = cols[ri(R, 0, cols.length - 1)], z = zs + 1 + ri(R, 0, (mask[c] & 7) - 1), i = z * PLANE + c;
        if (ok(i, rule)) { cur = i; break; }
      }
      if (cur < 0) continue;
      const len = rule.gem ? ri(R, V.gem[0], V.gem[1]) : ri(R, V.len[0], V.len[1]);
      let got = 1;
      L.ore[cur] = rule.ore;
      for (let step = 0; step < len * 4 && got < len; step++) {
        const x = cur % W, y = ((cur % PLANE) / W) | 0, z = (cur / PLANE) | 0;
        let nx = x, ny = y, nz = z;
        if (rf(R) * 100 < V.upPct) nz += rf(R) < 0.5 ? -1 : 1;
        else { const d = ri(R, 0, 3); nx += d === 1 ? 1 : d === 3 ? -1 : 0; ny += d === 2 ? 1 : d === 0 ? -1 : 0; }
        if (nx < 0 || ny < 0 || nx >= W || ny >= H) continue;
        const j = idx(nx, ny, nz);
        if (L.ore[j] === rule.ore) { cur = j; continue; }
        if (!ok(j, rule)) continue;
        L.ore[j] = rule.ore; cur = j; got++;
      }
      cells += got; placed++;
    }
    stats[rule.id] = { veins: placed, voxels: cells };
  }
  return stats;
}

/** Copy a D = 1 bitset into level z of an N-bit bitset. */
function copyBits(dst, src, z) {
  const base = z * PLANE;
  if (base % 8 === 0 && PLANE % 8 === 0) { dst.set(src.subarray(0, PLANE >> 3), base >> 3); return; }
  for (let c = 0; c < PLANE; c++) if (getBit(src, c)) setBit(dst, base + c, 1);
}

/** The plane voxels of the save that hold the old start (the Hearth), for mapgen3's guarantees. */
function hearthCtx(s) {
  const h = s.colony.hearth && s.colony.hearth.id !== null && s.colony.hearth.id !== undefined ? s.bld[s.colony.hearth.id] : null;
  if (!h) return {};
  const size = 20, x0 = Math.max(0, Math.min(W - size, h.x - (size >> 1))), y0 = Math.max(0, Math.min(H - size, h.y - (size >> 1)));
  return { hx: h.x + 1, hy: h.y + 1, site: { x0, y0, size } };
}

// ---- the migration --------------------------------------------------------------------------------------
/**
 * 5.4 over a live D = 1 state. Mutates and returns s (now D = 20, zS = 14), with the pristine world attached.
 * opts.chronicle (default true): write the Chronicle line.
 */
export function migrateWorld(s, opts = {}) {
  if ((s.d || 1) !== 1) throw new Error('migrate4: the colony already has depth.');
  const w = s.w, h = s.h, seed = s.seed >>> 0, old = s.L;
  const { d, zS: zs } = MIG4;
  // 1. world shape (PLANE is unchanged, so plane indexes stay valid across the switch)
  setMapSize(w, h, d, zs);
  const L = allocLayers();
  L.fluid = new Uint8Array(N);
  L.terrain.fill(TER.AIR);
  // 2. baseMask from the save: massif = rock, or a mined tile under a natural roof (2 THIN, 3 MOUNTAIN)
  const massif = new Uint8Array(PLANE);
  for (let c = 0; c < PLANE; c++) massif[c] = old.terrain[c] === TER.ROCK || old.roof[c] === ROOF.THIN || old.roof[c] === ROOF.MOUNTAIN ? 1 : 0;
  const { mask: baseMask, depth2 } = baseMaskOf(old.terrain, massif);
  // 5. levels 0..zS-1 from the seed and the mask only (before the plane copy: belowOnly writes nothing at z >= zS)
  const below = generateBelow(L, baseMask, seed, { ...hearthCtx(s), depth2, belowOnly: true });
  // 3. plane zS: the save's 12 layers; roof 2 and 3 cleared (real rock above replaces them), fluid 0
  const base = zs * PLANE;
  for (const l of LAYERS) {
    if (l.enc === 1) copyBits(L[l.name], old[l.name], zs);
    else L[l.name].set(old[l.name].subarray(0, PLANE), base);
  }
  L.fluid.fill(0, base, base + PLANE);
  for (let c = 0; c < PLANE; c++) { const r = L.roof[base + c]; if (r === ROOF.THIN || r === ROOF.MOUNTAIN) L.roof[base + c] = ROOF.OPEN; }
  // 4. the risen massif: zS+1..zS+h rock of the column's stone
  let risen = 0;
  for (let c = 0; c < PLANE; c++) {
    const hh = baseMask[c] & 7;
    if (!hh) continue;
    const mt = old.mat[c];
    for (let z = zs + 1; z <= zs + hh; z++) { const i = z * PLANE + c; L.terrain[i] = TER.ROCK; L.mat[i] = mt; risen++; }
  }
  const veins = massifVeins(L, baseMask, depth2, zs, seed);
  // 6. the pristine world: the plane as saved (dug), steps 4 and 5, and baseMask in the meta
  const meta = { dormant: below.rows, amendments: [], baseMask: toBase64(baseMask), migrated: { tick: s.tick, w, h } };
  const players = {};
  for (const name of PRISTINE_LAYERS) players[name] = L[name].slice();
  const p = makePristine({ w, h, d, zS: zs, genVersion: GEN3.legacyVersion, worldKind: WORLD_KIND.MIGRATED, layers: players, meta });
  // 7. entities at zS
  s.L = L; s.d = d; s.zS = zs;
  for (const key of ['col', 'items', 'bld', 'anim', 'foes']) for (const e of s[key]) if (e) e.z = zs;
  // 8. every saved voxel index + zS * PLANE (schema VOXEL_REFS and the tile/path fields; then the records schema does not list)
  let refs = mapVoxelRefs(s, (v) => v + base);
  const wr = s.colony.world;
  if (wr) for (const k of ['fire', 'caveQ', 'litDays']) for (const r of wr[k] || []) if (Array.isArray(r)) { r[0] = offTile(r[0], base); refs++; }
  for (const live of Object.values(s.st.live || {})) {
    if (!live) continue;
    for (const k of ['fell', 'loot']) if (Array.isArray(live[k])) { live[k] = live[k].map((v) => offTile(v, base)); refs += live[k].length; }
  }
  // 9. saved flow fields dropped (rebuilt from the state); a live raid's morale from its losses so far
  if (s.rt) s.rt.flow = [];
  for (const r of s.raids) {
    if (!r || r.stage === 'warned' || r.stage === 'ended') continue;
    const live = (s.st.live || {})[r.id];
    const lost = live ? live.lost | 0 : 0;
    r.morale = Math.max(0, 100 - 3 * lost);
  }
  // the generated buildings of the levels below (vault walls and chests), after every saved one
  for (const [def, x, y, mat, init, z] of below.bld) s.bld.push(newBuilding(s.bld.length, def, x, y, 0, mat, { ...init, st: 'done', z }));
  attachPristine(s, p);
  // 10. the runtime, the loot of the levels below, the Chronicle line
  initRuntime(s);
  for (const [k, m, n, x, y, name, z] of below.loot) spawnItem(s, k, m, 0, n, x, y, name ? { name, z } : { z });
  if (s.rt.dirty) s.rt.dirty.light = true;
  if (opts.chronicle !== false) s.chron.push([s.tick, 'world', CHRON_DEPTH, {}]);
  const info = { baseMask, depth2, refs, risen, veins, below: below.info, dormant: below.rows.length, pristine: p };
  return { s, pristine: p, info };
}

// ---- checks (5.4; tools/tests/migrate4.test.mjs) -----------------------------------------------------------
const solidT = (t) => t === TER.ROCK || t === TER.RUBBLE || t === TER.VOID;
/** The saved voxel indexes of a state (the ones the migration moved), as a flat list. */
export function savedVoxels(s) {
  const out = [];
  mapVoxelRefs(s, (v) => { out.push(v); return v; });
  const wr = s.colony.world;
  if (wr) for (const k of ['fire', 'caveQ', 'litDays']) for (const r of wr[k] || []) if (Array.isArray(r)) out.push(r[0]);
  for (const live of Object.values(s.st.live || {})) if (live) for (const k of ['fell', 'loot']) for (const v of live[k] || []) out.push(v);
  return out;
}
/** Errors of the 5.4 checks on a migrated state; [] when every check holds. */
export function checkMigrated(s, info, pre = null) {
  const errs = [], zs = s.zS, base = zs * PLANE, L = s.L;
  // every old tunnel voxel at zS has cover >= 1 (rock directly above)
  if (pre) for (const c of pre.tunnels) {
    if (L.terrain[base + PLANE + c] !== TER.ROCK) { errs.push(`tunnel ${c % W},${(c / W) | 0}: no rock above`); if (errs.length > 20) break; }
  }
  // nobody on AIR or inside a solid voxel; every colonist's voxel walkable
  const T = 32;
  for (const [key, label] of [['col', 'colonist'], ['anim', 'animal'], ['foes', 'foe']]) for (const e of s[key]) {
    if (!e || (e.hp && e.hp.dead)) continue;
    const i = idx(Math.floor(e.x / T), Math.floor(e.y / T), e.z);
    const t = L.terrain[i];
    if (e.z !== zs) errs.push(`${label} ${e.id}: z ${e.z}`);
    if (t === TER.AIR || solidT(t) || !TER_FLOOR[t]) errs.push(`${label} ${e.id}: on ${t}`);
    if (key === 'col' && !(TER_PASSABLE[t] || s.rt.walkCost[i] > 0)) errs.push(`colonist ${e.id}: not walkable`);
  }
  for (const key of ['items', 'bld']) for (const e of s[key]) {
    if (!e) continue;
    const i = idx(e.x, e.y, e.z), t = L.terrain[i];
    if (e.z === zs && t === TER.AIR) errs.push(`${key} ${e.id}: on air`);
  }
  // every tile field inside the map at z = zS (the migrated ones; the generated levels below add none)
  for (const v of savedVoxels(s)) if (!(v >= base && v < base + PLANE)) { errs.push(`voxel index ${v} not at z ${zs}`); if (errs.length > 40) break; }
  // the pristine record's CRCs
  const p = info.pristine, crc = layerCrcs(p.layers, p.w * p.h * p.d);
  for (let k = 0; k < 13; k++) if ((crc[k] >>> 0) !== (p.crc[k] >>> 0)) errs.push(`pristine crc ${k}`);
  return errs;
}
/** Before the migration: the old tunnel voxels (mined floor under a natural roof) of a D = 1 state. */
export function preMigration(s) {
  const tunnels = [];
  for (let c = 0; c < PLANE; c++) if ((s.L.roof[c] === ROOF.THIN || s.L.roof[c] === ROOF.MOUNTAIN) && s.L.terrain[c] !== TER.ROCK) tunnels.push(c);
  return { tunnels };
}
